  const parse=key=>{try{return JSON.parse(localStorage.getItem(key)||"[]")}catch{return[]}},recent=parse("xart-recent-reading"),savedArticles=parse("xart-saved-articles"),savedDiscussions=parse("xart-community-saved"),knowledge=parse("xart-knowledge-base"),downloads=parse("xart-download-history"),notes=Object.keys(localStorage).filter(key=>key.startsWith("xart-note-")&&localStorage.getItem(key)?.trim()).map(key=>({id:key,text:localStorage.getItem(key)}));
