  const panels=[{id:"recent",title:labels.recent,count:recentItems.length,Icon:BookOpen,content:recentItems.map(item=><button key={item.id||item.n} onClick={()=>onRead(item)}><b>{item[lang]?.[0]}</b><small>{item.tag} · {labels.read}</small></button>)},{id:"articles",title:labels.articles,count:savedItems.length,Icon:BookMarked,content:savedItems.map(item=><button key={item.id||item.n} onClick={()=>onRead(item)}><b>{item[lang]?.[0]}</b><small>{item.tag}</small></button>)},{id:"discussions",title:labels.discussions,count:savedDiscussions.length,Icon:MessageCircle},{id:"ai",title:labels.ai,count:knowledge.length,Icon:Sparkles,content:knowledge.slice(0,3).map(item=><div key={item.id}><b>{item.article||labels.ai}</b><small>{String(item.result||"").slice(0,90)}</small></div>)},{id:"notes",title:labels.notes,count:notes.length,Icon:Pencil,content:notes.slice(0,3).map(item=><div key={item.id}><b>{labels.notes}</b><small>{item.text.slice(0,90)}</small></div>)},{id:"downloads",title:labels.downloads,count:downloads.length,Icon:Download,content:downloads.slice(0,3).map((item,index)=><div key={index}><b>{item.title}</b><small>{new Date(item.date).toLocaleDateString()}</small></div>)}];
